SELECT e.relation,e.trigger,t.oid IS NOT NULL AND t.tgenabled='O' AS present_enabled,t.tgfoid::regprocedure::text=e.function AS expected_function,pg_get_triggerdef(t.oid,true) AS inspect_exact_event_and_column_set FROM (VALUES ('training_session_records','guard_completion_record_identity_v1','cohort_guard_completion_record_identity_v1()'),('training_session_records','trg_sync_training_session_from_terminal_record','cohort_sync_training_session_from_terminal_record()'),('training_block_results','guard_direct_result_write_v1','cohort_guard_direct_result_write_v1()'),('training_block_results','guard_result_identity_v1','cohort_guard_result_identity_v1()'),('training_exercise_results','guard_direct_result_write_v1','cohort_guard_direct_result_write_v1()'),('training_exercise_results','guard_result_identity_v1','cohort_guard_result_identity_v1()'),('training_set_results','guard_direct_result_write_v1','cohort_guard_direct_result_write_v1()'),('training_set_results','guard_result_identity_v1','cohort_guard_result_identity_v1()')) e(relation,trigger,function) LEFT JOIN pg_trigger t ON t.tgrelid=('public.'||e.relation)::regclass AND t.tgname=e.trigger ORDER BY e.relation,e.trigger;
